import itertools
import re

def levenshtein_distance(a, b):
    if len(a) < len(b):
        return levenshtein_distance(b, a)
    if len(b) == 0:
        return len(a)
    previous_row = range(len(b) + 1)
    for i, ca in enumerate(a):
        current_row = [i + 1]
        for j, cb in enumerate(b):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (ca != cb)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row
    return previous_row[-1]

GIBBERISH_FILE = 'gibberish_strings.txt'
FLAG_FMT = re.compile(r"flag\{[A-Za-z0-9_]{12,24}\}")

gibberish = []
with open(GIBBERISH_FILE) as f:
    gibberish = [line.strip() for line in f if line.strip()]

charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
def check_candidate(candidate):
    return sum(levenshtein_distance(candidate, gib) for gib in gibberish)

best_sum = 1<<30
best_candidate = None
for x in charset:
    cand = f"flag{{{x*14}}}"
    total = check_candidate(cand)
    if total < best_sum:
        best_sum = total
        best_candidate = cand
    if total == 505:
        print(f"Found: {cand} sum={total}")
        break
for offset in range(len(charset)-14):
    body = charset[offset:offset+14]
    cand = f"flag{{{body}}}"
    total = check_candidate(cand)
    if total < best_sum:
        best_sum = total
        best_candidate = cand
    if total == 505:
        print(f"Found: {cand} sum={total}")
        break
print(f"Best: {best_candidate} Levenshtein sum={best_sum}")

