from Levenshtein import distance as levenshtein_distance
import re

# Load gibberish strings
with open('gibberish_strings.txt') as f:
    gibberish = [line.strip() for line in f if line.strip()]

# The flag must match flag{...} and have length 20 to match the gibberish length
prefix = 'flag{'
suffix = '}'
inner_len = 14  # 6 outside (flag{}), 14 inside

charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'

# A simple approach: Try short brute-force, then try single edit distance from one gibberish
# But first, check the effect of putting a gibberish string inside the flag format
def total_dist(s):
    return sum(levenshtein_distance(s, g) for g in gibberish)

def is_flag_format(s):
    return bool(re.fullmatch(r'flag\{[A-Za-z0-9_]{14}\}', s))

best_score = None
best_str = None

for gib in gibberish:
    candidate = f'flag{{{gib[:14]}}}'
    if is_flag_format(candidate) and len(candidate)==20:
        score = total_dist(candidate)
        if best_score is None or score < best_score:
            best_score = score
            best_str = candidate

# If none found, try all substrings of gibberish, or bruteforce more...
if best_str is None or best_score != 505:
    # Try single edit distance from each gibberish (bruteforce change one char to all possible)
    for gib in gibberish:
        base = gib[:14]
        for i in range(14):
            for c in charset:
                test_val = base[:i]+c+base[i+1:]
                candidate = f'flag{{{test_val}}}'
                if is_flag_format(candidate) and len(candidate)==20:
                    score = total_dist(candidate)
                    if score == 505:
                        best_str = candidate
                        best_score = score
                        break
            if best_score == 505:
                break
        if best_score == 505:
            break

print('Best candidate:', best_str)
print('Sum distance:', best_score)

import re

def levenshtein_distance(a, b):
    # Standard DP implementation
    n, m = len(a), len(b)
    if n > m:
        a, b = b, a
        n, m = m, n
    prev = list(range(n+1))
    for i in range(1, m+1):
        curr = [i]+[0]*n
        for j in range(1, n+1):
            ins = prev[j]+1
            dele = curr[j-1]+1
            subs = prev[j-1]+(a[j-1] != b[i-1])
            curr[j] = min(ins, dele, subs)
        prev = curr
    return prev[n]

# Load gibberish strings
